gaiz(){return"\u5237\u65b0\u5904\u7406\u7ed3\u679c"},
gaip(){return"\u8fd9\u6761\u8bc4\u8bba\u76ee\u524d\u5bf9\u5176\u4ed6\u4eba\u4e0d\u53ef\u89c1\u3002"},
gair(){return"\u670d\u52a1\u7aef\u786e\u8ba4\u8fd9\u6761\u8bc4\u8bba\u5df2\u6062\u590d\u53ef\u89c1\u3002"},
gaiy(){return"\u5904\u7406\u539f\u56e0"},
